#include <bits/stdc++.h>
using namespace std;

class SegmentTree {
private:
    int size;
    vector<int> tree;
    int inf;

public:
    SegmentTree(int count, int infValue) : inf(infValue) {
        size = 1;
        while (size < count) {
            size <<= 1;
        }
        tree.assign(size * 2, inf);
    }

    void update(int index, int value) {
        int pos = size + index;
        tree[pos] = value;
        for (pos >>= 1; pos >= 1; pos >>= 1) {
            tree[pos] = min(tree[pos * 2], tree[pos * 2 + 1]);
            if (pos == 1) {
                break;
            }
        }
    }

    int rangeMin(int left, int right) const {
        if (left > right) {
            return inf;
        }
        left += size;
        right += size;
        int answer = inf;
        while (left <= right) {
            if (left & 1) {
                answer = min(answer, tree[left++]);
            }
            if (!(right & 1)) {
                answer = min(answer, tree[right--]);
            }
            left >>= 1;
            right >>= 1;
        }
        return answer;
    }
};

